do $$
begin
  if to_regclass('public.knowledge_units') is null then
    raise exception E'\n\n>>> DỪNG LẠI: Phải chạy 01-schema.sql TRƯỚC tệp này. <<<\n';
  end if;
  if to_regclass('public.error_hints') is null then
    raise exception E'\n\n>>> DỪNG LẠI: Phải chạy 05-goi-y-theo-tang.sql TRƯỚC tệp này. <<<\n';
  end if;
  if to_regclass('public.micro_lessons') is null then
    raise exception E'\n\n>>> DỪNG LẠI: Phải chạy 08-vi-bai-hoc.sql TRƯỚC tệp này. <<<\n';
  end if;
  if to_regclass('public.mm_activities') is null then
    raise exception E'\n\n>>> DỪNG LẠI: Phải chạy 35-mathmind.sql TRƯỚC tệp này. <<<\n';
