-- ------------------------------------------------ 0. CỘT HÌNH VẼ / BIỂU ĐỒ CHO CÂU HỎI
-- jsonb: {"loai":"quat"|"doan-thang"|"hinh", ...}. Học sinh được đọc (không chứa đáp án).
alter table public.questions add column if not exists hinh jsonb;
alter table public.contents add column if not exists nguon text;
grant select (hinh) on public.questions to authenticated;

-- Trạng thái duyệt (22/11/2026): nhap | da-duyet | can-sua. Câu "can-sua" bị ẩn khỏi questions_public (học sinh không thấy).
alter table public.questions add column if not exists trang_thai text not null default 'nhap';
alter table public.questions add column if not exists ghi_chu_gv text;
alter table public.questions add column if not exists nguoi_duyet text;
alter table public.questions add column if not exists ngay_duyet date;
do $ck$ begin
  alter table public.questions add constraint questions_trang_thai_ck check (trang_thai in ('nhap', 'da-duyet', 'can-sua'));
exception when duplicate_object then null; end $ck$;
create or replace view public.questions_public
with (security_invoker = true) as
  select question_id, ku_id, level, stem, expected_time_sec, hinh from public.questions where trang_thai <> 'can-sua';
-- View chạy bằng quyền của người xem nên học sinh cần quyền đọc cột trang_thai (không nhạy cảm) để lọc câu.
grant select (trang_thai) on public.questions to authenticated;

-- ===========================================================================
-- CHƯƠNG IV — HỆ THỨC LƯỢNG TRONG TAM GIÁC VUÔNG
-- ===========================================================================
on conflict (ku_id) do update set lesson_id = excluded.lesson_id, ku_name = excluded.ku_name,
  order_index = excluded.order_index, prerequisite_ku = excluded.prerequisite_ku, co_video = excluded.co_video;

-- Link video: chỉ điền khi ô còn trống — link giáo viên đã tự gắn ở /gv/noi-dung được giữ nguyên.
on conflict (content_id) do update set title = excluded.title, ku_id = excluded.ku_id,
  duration_sec = case when contents.url is null or contents.url = '' then excluded.duration_sec else contents.duration_sec end,
  nguon = case when contents.url is null or contents.url = '' then excluded.nguon else contents.nguon end,
  url = case when contents.url is null or contents.url = '' then excluded.url else contents.url end;

on conflict (error_code) do update set ku_id = excluded.ku_id, misconception = excluded.misconception,
  remediation_id = excluded.remediation_id;

on conflict (question_id) do update set ku_id = excluded.ku_id, level = excluded.level, stem = excluded.stem,
  correct_option = excluded.correct_option,
  expected_time_sec = excluded.expected_time_sec, hinh = excluded.hinh,
  trang_thai = excluded.trang_thai, ghi_chu_gv = excluded.ghi_chu_gv, nguoi_duyet = excluded.nguoi_duyet, ngay_duyet = excluded.ngay_duyet;

on conflict (question_id, option_key) do update set option_text = excluded.option_text;

on conflict (question_id, option_key) do update set error_code = excluded.error_code;

on conflict (error_code, tier) do update set hint_text = excluded.hint_text;

on conflict (content_id) do update set dan = excluded.dan, quy_tac = excluded.quy_tac,
  vi_du = excluded.vi_du, tu_lam = excluded.tu_lam, updated_at = now();

-- ===========================================================================
-- NGÂN HÀNG HOẠT ĐỘNG TOÁN 9 (bản nháp; giữ nguyên nếu giáo viên đã sửa)
-- ===========================================================================
on conflict (activity_id) do nothing;

-- ------------------------------------------------ KIỂM TRA SAU KHI CHẠY
select split_part(ku_id, '-', 1) as chuong, count(*) as so_cau, count(hinh) as co_hinh
from questions group by 1 order by length(split_part(ku_id, '-', 1)), 1;
