  ('VBH-HTL-01', 'C4-B12-M1', 'micro-lesson', 1, 'Vi bài học: Cạnh góc vuông = huyền × sin góc đối = huyền × cos góc kề', 360, null, null),
  ('VBH-HTL-02', 'C4-B12-M2', 'micro-lesson', 1, 'Vi bài học: Cạnh góc vuông = cạnh kia × tan góc đối = × cot góc kề', 360, null, null),
