insert into error_dictionary (error_code, ku_id, misconception, remediation_id) values
  ('E-TSLG-01', 'C4-B11-M1', 'Xác định cạnh đối, cạnh kề sai (lấy theo góc vuông hoặc theo góc kia) nên viết sin, cos, tan sai. Ví dụ: Tam giác ABC vuông tại A: sin B = AB/BC', 'VBH-TSLG-01'),
  ('E-TSLG-02', 'C4-B11-M1', 'Nhớ đảo định nghĩa (sin = kề/huyền, tan = kề/đối), lấy huyền ở tử, hoặc cho rằng sin, cos có thể lớn hơn 1. Ví dụ: sin α = huyền/đối; tan B = AB/AC', 'VBH-TSLG-02'),
  ('E-TSLG-03', 'C4-B11-M2', 'Nhớ nhầm giá trị sin, cos, tan của 30°, 45°, 60° (đổi chỗ 1/2 và √3/2, √3 và √3/3). Ví dụ: sin 30° = √3/2; tan 60° = √3/3', 'VBH-TSLG-03'),
  ('E-TSLG-04', 'C4-B11-M3', 'Nhầm góc phụ với góc bù, hoặc cho rằng sin α = sin(90° − α). Ví dụ: sin 50° = sin 40°; hai góc phụ nhau có tổng 180°', 'VBH-TSLG-04'),
  ('E-HTL-01', 'C4-B12-M1', 'Tính cạnh góc vuông bằng cạnh huyền nhân sai tỉ số (sin thay cos), hoặc chia thay vì nhân. Ví dụ: BC = 12, góc B = 60°: AB = 12·sin 60°', 'VBH-HTL-01'),
  ('E-HTL-02', 'C4-B12-M2', 'Tính cạnh góc vuông từ cạnh góc vuông kia mà dùng tan của góc kề (hoặc chia cho tan) sai. Ví dụ: AB = 3, góc B = 60°: AC = 3·tan 30°', 'VBH-HTL-02'),
  ('E-HTL-03', 'C4-B12-M3', 'Bấm máy ở chế độ radian, làm tròn sai, hoặc xác định sai góc nâng, góc hạ trong bài toán thực tế. Ví dụ: Góc hạ 25° từ toà nhà cao 30 m: khoảng cách = 30·tan 25°', 'VBH-HTL-03'),
  ('E-HTL-04', 'C4-B12-M3', 'Tính góc còn lại theo tổng 180° bỏ qua góc vuông, hoặc giải tam giác vuông còn thiếu yếu tố. Ví dụ: Góc B = 35° thì góc C = 145°', 'VBH-HTL-04')
