  ('C4-B11-M1-Q05', 'C4-B11-M1', 3, 'Cho góc nhọn $\alpha$ có $\sin \alpha = \dfrac{3}{5}$. Khi đó $\cos \alpha$ bằng:', 'A', 90, null, 'nhap', null, null, null),
  ('C4-B11-M1-Q06', 'C4-B11-M1', 3, 'Tam giác $MNP$ vuông tại $M$ có $MN = 6$, $NP = 10$. $\sin P$ bằng:', 'A', 90, '{"loai":"tam-giac-vuong","dinh":["M","N","P"],"canh":{"tren":"6","huyen":"10"},"moTa":"Tam giác MNP vuông tại M; NM = 6, NP = 10."}'::jsonb, 'nhap', null, null, null),
  ('C4-B11-M1-Q07', 'C4-B11-M1', 2, 'Với mọi góc nhọn $\alpha$, khẳng định nào đúng?', 'A', 60, null, 'nhap', null, null, null),
  ('C4-B11-M1-Q08', 'C4-B11-M1', 4, 'Một chiếc thang dài $4$ m dựa vào tường, chân thang cách chân tường $1{,}5$ m. Gọi $\alpha$ là góc giữa thang và mặt đất. $\cos \alpha$ bằng:', 'A', 120, '{"loai":"tam-giac-vuong","dinh":["","",""],"canh":{"ngang":"1,5 m","huyen":"4 m"},"goc":{"phai":"α"},"nhanCanh":{"tren":"tường","ngang":"mặt đất","huyen":"thang"},"moTa":"Thang dài 4 m dựa vào tường, chân thang cách chân tường 1,5 m, α là góc giữa thang và mặt đất."}'::jsonb, 'nhap', null, null, null),
  ('C4-B11-M1-Q09', 'C4-B11-M1', 1, 'Tam giác $ABC$ vuông tại $A$. Cạnh kề của góc $C$ là:', 'A', 45, null, 'nhap', null, null, null),
  ('C4-B11-M1-Q10', 'C4-B11-M1', 1, 'Tam giác $ABC$ vuông tại $A$. $\cos B$ bằng:', 'A', 45, null, 'nhap', null, null, null),
  ('C4-B11-M1-Q11', 'C4-B11-M1', 2, 'Tam giác $ABC$ vuông tại $A$ có $AB = 6$, $AC = 8$, $BC = 10$. $\sin C$ bằng:', 'A', 60, '{"loai":"tam-giac-vuong","dinh":["A","B","C"],"canh":{"tren":"6","ngang":"8","huyen":"10"},"moTa":"Tam giác ABC vuông tại A; BA = 6, AC = 8, BC = 10."}'::jsonb, 'nhap', null, null, null),
  ('C4-B11-M1-Q12', 'C4-B11-M1', 2, 'Tam giác $ABC$ vuông tại $A$ có $AB = 6$, $AC = 8$, $BC = 10$. $\cot B$ bằng:', 'A', 60, '{"loai":"tam-giac-vuong","dinh":["A","B","C"],"canh":{"tren":"6","ngang":"8","huyen":"10"},"moTa":"Tam giác ABC vuông tại A; BA = 6, AC = 8, BC = 10."}'::jsonb, 'nhap', null, null, null),
  ('C4-B11-M1-Q13', 'C4-B11-M1', 3, 'Tam giác $ABC$ vuông tại $A$ có $AB = 5$, $BC = 13$. $\tan B$ bằng:', 'A', 90, '{"loai":"tam-giac-vuong","dinh":["A","B","C"],"canh":{"tren":"5","huyen":"13"},"moTa":"Tam giác ABC vuông tại A; BA = 5, BC = 13."}'::jsonb, 'nhap', null, null, null),
  ('C4-B11-M1-Q14', 'C4-B11-M1', 3, 'Cho góc nhọn $\alpha$ có $\cos \alpha = 0{,}6$. Khi đó $\tan \alpha$ bằng:', 'A', 90, null, 'nhap', null, null, null),
  ('C4-B11-M1-Q15', 'C4-B11-M1', 4, 'Tam giác $ABC$ vuông tại $A$ có $AB = 5$ cm, $BC = 13$ cm. Giá trị của $\tan C + \cot B$ là:', 'A', 120, '{"loai":"tam-giac-vuong","dinh":["A","B","C"],"canh":{"tren":"5 cm","huyen":"13 cm"},"moTa":"Tam giác ABC vuông tại A; BA = 5 cm, BC = 13 cm."}'::jsonb, 'nhap', null, null, null),
  ('C4-B11-M1-Q16', 'C4-B11-M1', 4, 'Một con dốc có mặt dốc dài $50$ m, đỉnh dốc cao hơn chân dốc $14$ m. Gọi $\alpha$ là góc giữa mặt dốc và phương nằm ngang. $\tan \alpha$ bằng:', 'A', 120, '{"loai":"tam-giac-vuong","dinh":["","",""],"canh":{"tren":"14 m","huyen":"50 m"},"goc":{"phai":"α"},"nhanCanh":{"tren":"độ cao","huyen":"mặt dốc"},"moTa":"Mặt dốc dài 50 m, đỉnh dốc cao hơn chân dốc 14 m, α là góc giữa mặt dốc và phương nằm ngang."}'::jsonb, 'nhap', null, null, null),
