  ('C4-B11-M2-Q06', 'C4-B11-M2', 3, 'Giá trị của $\tan 45^{\circ} \cdot \cot 45^{\circ} + \sin ^{2} 45^{\circ}$ là:', 'A', 90, null, 'nhap', null, null, null),
  ('C4-B11-M2-Q07', 'C4-B11-M2', 2, 'Tam giác $ABC$ vuông tại $A$ có góc $B = 30^{\circ}$, $BC = 10$ cm. Độ dài $AC$ là:', 'A', 60, '{"loai":"tam-giac-vuong","dinh":["A","B","C"],"canh":{"ngang":"?","huyen":"10 cm"},"goc":{"tren":"30°"},"moTa":"Tam giác ABC vuông tại A; AC cần tìm, BC = 10 cm, góc B = 30°."}'::jsonb, 'nhap', null, null, null),
