  ('C4-B11-M2-Q14', 'C4-B11-M2', 4, 'Một hình thoi có cạnh $10$ cm và một góc bằng $60^{\circ}$. Diện tích hình thoi (làm tròn đến hàng phần mười) là:', 'A', 120, null, 'nhap', null, null, null),
  ('C4-B11-M2-Q15', 'C4-B11-M2', 4, 'Một chiếc thang dài $6$ m dựa vào tường, tạo với mặt đất góc $60^{\circ}$. Đầu thang chạm tường ở độ cao khoảng (làm tròn đến hàng phần mười):', 'A', 120, '{"loai":"tam-giac-vuong","dinh":["","",""],"canh":{"tren":"?","huyen":"6 m"},"goc":{"phai":"60°"},"nhanCanh":{"tren":"tường","ngang":"mặt đất","huyen":"thang"},"moTa":"Thang dài 6 m dựa vào tường, tạo với mặt đất góc 60°; cần tìm độ cao đầu thang chạm tường."}'::jsonb, 'nhap', null, null, null),
