insert into error_hints (error_code, tier, hint_text) values
  ('E-TSLG-01', 1, 'Đứng ở góc đang xét, cạnh nào nằm đối diện góc đó? Cạnh góc vuông nào nằm sát góc đó?'),
  ('E-TSLG-01', 2, 'Với một góc nhọn: cạnh huyền là cạnh đối diện góc vuông; cạnh đối là cạnh góc vuông nằm đối diện góc đang xét; cạnh kề là cạnh góc vuông còn lại (một đầu nằm ở góc đó).'),
  ('E-TSLG-01', 3, 'Ví dụ: tam giác $ABC$ vuông tại $A$, với góc $B$: cạnh đối $AC$, cạnh kề $AB$, cạnh huyền $BC$; $\sin B = AC/BC$.'),
  ('E-TSLG-02', 1, '$\sin$ là tỉ số của cạnh nào chia cạnh nào? Cạnh huyền nằm ở tử hay ở mẫu?'),
  ('E-TSLG-02', 2, '$\sin =$ đối$/$huyền, $\cos =$ kề$/$huyền, $\tan =$ đối$/$kề, $\cot =$ kề$/$đối. Vì cạnh huyền lớn nhất nên $0 < \sin$, $\cos < 1$. Còn $\sin ^{2} \alpha + \cos ^{2} \alpha = 1$.'),
  ('E-TSLG-02', 3, 'Ví dụ: $AB = 3$, $AC = 4$, $BC = 5$: $\tan B = AC/AB = \dfrac{4}{3}$; $\sin \alpha = \dfrac{3}{5}$ thì $\cos \alpha = \dfrac{4}{5}$.'),
  ('E-TSLG-03', 1, 'Trong tam giác đều cạnh $2$, kẻ đường cao thì có tam giác vuông với các góc bao nhiêu độ?'),
  ('E-TSLG-03', 2, '$\sin 30^{\circ} = \cos 60^{\circ} = \dfrac{1}{2}$; $\sin 60^{\circ} = \cos 30^{\circ} = \sqrt{3}/2$; $\sin 45^{\circ} = \cos 45^{\circ} = \sqrt{2}/2$; $\tan 30^{\circ} = \sqrt{3}/3$, $\tan 45^{\circ} = 1$, $\tan 60^{\circ} = \sqrt{3}$. Góc lớn hơn thì $\sin$ lớn hơn.'),
  ('E-TSLG-03', 3, 'Ví dụ: $BC = 10$, góc $B = 30^{\circ}$: $AC = 10\cdot \sin 30^{\circ} = 5$; $\tan \alpha = \sqrt{3}/3$ thì $\alpha = 30^{\circ}$.'),
  ('E-TSLG-04', 1, 'Hai góc phụ nhau có tổng bằng bao nhiêu độ: $90^{\circ}$ hay $180^{\circ}$?'),
  ('E-TSLG-04', 2, '$\alpha$ và $90^{\circ} - \alpha$ là hai góc phụ nhau: $\sin \alpha = \cos (90^{\circ} - \alpha )$, $\cos \alpha = \sin (90^{\circ} - \alpha )$, $\tan \alpha = \cot (90^{\circ} - \alpha )$. Trong tam giác vuông, hai góc nhọn phụ nhau nên $\sin B = \cos C$.'),
  ('E-TSLG-04', 3, 'Ví dụ: $\sin 50^{\circ} = \cos 40^{\circ}$; $\tan 20^{\circ} \cdot \tan 70^{\circ} = \tan 20^{\circ} \cdot \cot 20^{\circ} = 1$.'),
  ('E-HTL-01', 1, 'Cạnh cần tìm nằm đối diện hay nằm kề với góc đã biết?'),
  ('E-HTL-01', 2, 'Cạnh góc vuông $=$ cạnh huyền $\times \sin$ góc đối $=$ cạnh huyền $\times \cos$ góc kề. Biết cạnh góc vuông, tìm cạnh huyền thì chia cho $\sin$ (hoặc $\cos$).'),
  ('E-HTL-01', 3, 'Ví dụ: $BC = 12$, góc $B = 60^{\circ}$: $AB$ kề góc $B$ nên $AB = 12\cdot \cos 60^{\circ} = 6$.'),
  ('E-HTL-02', 1, 'Cạnh cần tìm đối diện góc đã biết hay kề góc đó? Cạnh đã biết là cạnh góc vuông hay cạnh huyền?'),
  ('E-HTL-02', 2, 'Cạnh góc vuông $=$ cạnh góc vuông kia $\times \tan$ góc đối $=$ cạnh góc vuông kia $\times \cot$ góc kề.'),
  ('E-HTL-02', 3, 'Ví dụ: $AB = 3$, góc $B = 60^{\circ}$: $AC$ đối góc $B$ nên $AC = AB\cdot \tan 60^{\circ} = 3\sqrt{3}$.'),
  ('E-HTL-03', 1, 'Máy tính đang ở chế độ độ $(D)$ chưa? Góc hạ nằm giữa tia nhìn và đường nào?'),
  ('E-HTL-03', 2, 'Để máy ở chế độ $D$. Góc nâng, góc hạ đều đo giữa tia nhìn và phương nằm ngang; vẽ hình, đánh dấu tam giác vuông rồi chọn tỉ số. Làm tròn ở bước cuối.'),
  ('E-HTL-03', 3, 'Ví dụ: toà nhà cao $30$ m, góc hạ $25^{\circ}$ thì khoảng cách $d$ thoả $\tan 25^{\circ} = \dfrac{30}{d}$, $d = 30/\tan 25^{\circ} \approx 64$ m.'),
  ('E-HTL-04', 1, 'Trong tam giác vuông, hai góc nhọn cộng lại bằng bao nhiêu độ?'),
  ('E-HTL-04', 2, 'Tam giác vuông có góc vuông $90^{\circ}$ nên hai góc nhọn có tổng $90^{\circ}$. Giải tam giác vuông là tìm mọi cạnh và góc chưa biết; cần biết ít nhất hai yếu tố (trong đó có một cạnh).'),
  ('E-HTL-04', 3, 'Ví dụ: góc $B = 35^{\circ}$ thì góc $C = 90^{\circ} - 35^{\circ} = 55^{\circ}$; $AB = AC$ thì góc $B =$ góc $C = 45^{\circ}$.')
insert into micro_lessons (content_id, dan, quy_tac, vi_du, tu_lam) values
  ('VBH-TSLG-01', '"Đối" hay "kề" luôn tính theo góc đang xét, không phải theo góc vuông.', 'Đứng ở góc nhọn đang xét: cạnh đối nằm đối diện góc; cạnh kề là cạnh góc vuông có một đầu ở góc đó; cạnh huyền đối diện góc vuông.', '[{"de":"Tam giác $ABC$ vuông tại $A$, viết $\\sin B$.","giai":"Cách nghĩ sai: $\\sin B = AB/BC$. Cách đúng: với góc $B$, cạnh đối là $AC$, nên $\\sin B = AC/BC$."},{"de":"Với góc $C$ trong tam giác trên, cạnh kề là gì?","giai":"Cạnh kề góc $C$ là $AC$."}]'::jsonb, '[{"de":"Cạnh đối góc $C$?","dapAn":"$AB$","giaiThich":"Đối diện $C$.","dapAnGoc":"AB"},{"de":"$\\cos B =$ ?","dapAn":"$AB/BC$","giaiThich":"Kề$/$huyền.","dapAnGoc":"AB/BC"}]'::jsonb),
  ('VBH-TSLG-02', 'Bốn tỉ số, bốn công thức — và một mẹo nhớ: "Sin đi học, Cos không hư, Tan đoàn kết, Cot kết đoàn".', '$\sin =$ đối$/$huyền, $\cos =$ kề$/$huyền, $\tan =$ đối$/$kề, $\cot =$ kề$/$đối. Cạnh huyền luôn ở mẫu của $\sin$, $\cos$ nên $0 < \sin$, $\cos < 1$; $\sin ^{2} \alpha + \cos ^{2} \alpha = 1$.', '[{"de":"$AB = 3$, $AC = 4$, $BC = 5$. $\\tan B$?","giai":"Cách nghĩ sai: $\\tan B = \\dfrac{3}{4}$ (kề$/$đối). Cách đúng: $\\tan B =$ đối$/$kề $= AC/AB = \\dfrac{4}{3}$."},{"de":"$\\sin \\alpha = \\dfrac{3}{5}$, tìm $\\cos \\alpha$.","giai":"$\\cos ^{2} \\alpha = 1 - \\dfrac{9}{25} = \\dfrac{16}{25}$, $\\cos \\alpha = \\dfrac{4}{5}$."}]'::jsonb, '[{"de":"$\\cot B$ trong tam giác trên?","dapAn":"$\\dfrac{3}{4}$","giaiThich":"Kề$/$đối.","dapAnGoc":"3/4"},{"de":"$\\sin \\alpha$ có thể bằng $1{,}2$?","dapAn":"Không","giaiThich":"Đối $<$ huyền.","dapAnGoc":"Không"}]'::jsonb),
  ('VBH-TSLG-03', 'Chỉ cần nhớ tam giác đều và tam giác vuông cân là dựng lại được bảng góc đặc biệt.', '$\sin 30^{\circ} = \dfrac{1}{2}$, $\sin 45^{\circ} = \sqrt{2}/2$, $\sin 60^{\circ} = \sqrt{3}/2$; $\cos$ thì ngược lại ($\cos 30^{\circ} = \sqrt{3}/2$, $\cos 60^{\circ} = \dfrac{1}{2}$); $\tan 30^{\circ} = \sqrt{3}/3$, $\tan 45^{\circ} = 1$, $\tan 60^{\circ} = \sqrt{3}$.', '[{"de":"$\\sin 30^{\\circ}$ bằng bao nhiêu?","giai":"Cách nghĩ sai: $\\sqrt{3}/2$. Cách đúng: trong nửa tam giác đều cạnh $2$, cạnh đối góc $30^{\\circ}$ bằng $1$, huyền bằng $2$: $\\sin 30^{\\circ} = \\dfrac{1}{2}$."},{"de":"Tìm $\\alpha$ biết $\\tan \\alpha = \\sqrt{3}/3$.","giai":"$\\tan 30^{\\circ} = \\sqrt{3}/3$ nên $\\alpha = 30^{\\circ}$."}]'::jsonb, '[{"de":"$\\cos 45^{\\circ}$?","dapAn":"$\\sqrt{2}/2$","giaiThich":"Tam giác vuông cân.","dapAnGoc":"√2/2"},{"de":"$\\tan 60^{\\circ}$?","dapAn":"$\\sqrt{3}$","giaiThich":"$\\sqrt{3}/2 : \\dfrac{1}{2}$.","dapAnGoc":"√3"}]'::jsonb),
  ('VBH-TSLG-04', 'Hai góc nhọn của tam giác vuông "đổi vai" cho nhau: $\sin$ góc này là $\cos$ góc kia.', '$\alpha + \beta = 90^{\circ}$ thì $\sin \alpha = \cos \beta$, $\cos \alpha = \sin \beta$, $\tan \alpha = \cot \beta$, $\cot \alpha = \tan \beta$. Phụ nhau là tổng $90^{\circ}$, bù nhau mới là tổng $180^{\circ}$.', '[{"de":"$\\sin 50^{\\circ}$ bằng?","giai":"Cách nghĩ sai: $\\sin 40^{\\circ}$. Cách đúng: $50^{\\circ}$ và $40^{\\circ}$ phụ nhau nên $\\sin 50^{\\circ} = \\cos 40^{\\circ}$."},{"de":"Tính $\\tan 20^{\\circ} \\cdot \\tan 70^{\\circ}$.","giai":"$\\tan 70^{\\circ} = \\cot 20^{\\circ}$ nên tích bằng $\\tan 20^{\\circ} \\cdot \\cot 20^{\\circ} = 1$."}]'::jsonb, '[{"de":"$\\cos 65^{\\circ} = \\sin$ ?","dapAn":"$25^{\\circ}$","giaiThich":"$90^{\\circ} - 65^{\\circ}$.","dapAnGoc":"25°"},{"de":"$\\sin ^{2} 20^{\\circ} + \\sin ^{2} 70^{\\circ}$?","dapAn":"$1$","giaiThich":"$\\sin 70^{\\circ} = \\cos 20^{\\circ}$.","dapAnGoc":"1"}]'::jsonb),
  ('VBH-HTL-01', 'Biết cạnh huyền và một góc là tính được cả hai cạnh góc vuông — chỉ cần chọn đúng $\sin$ hay $\cos$.', 'Cạnh góc vuông $=$ cạnh huyền $\times \sin$ góc đối $=$ cạnh huyền $\times \cos$ góc kề. Ngược lại, cạnh huyền $=$ cạnh góc vuông : $\sin$ góc đối.', '[{"de":"$BC = 12$, góc $B = 60^{\\circ}$, tìm $AB$.","giai":"Cách nghĩ sai: $AB = 12\\cdot \\sin 60^{\\circ} = 6\\sqrt{3}$. Cách đúng: $AB$ kề góc $B$ nên $AB = 12\\cdot \\cos 60^{\\circ} = 6$."},{"de":"$AC = 6$, góc $B = 30^{\\circ}$, tìm $BC$.","giai":"$AC$ đối góc $B$: $AC = BC\\cdot \\sin 30^{\\circ}$ nên $BC = 6 : 0{,}5 = 12$."}]'::jsonb, '[{"de":"$BC = 20$, góc $C = 30^{\\circ}$, $AB =$ ?","dapAn":"$10$","giaiThich":"$AB$ đối $C$: $20\\cdot \\sin 30^{\\circ}$.","dapAnGoc":"10"},{"de":"$BC = 10$, $\\cos B = 0{,}8$, $AB =$ ?","dapAn":"$8$","giaiThich":"$10\\cdot 0{,}8$.","dapAnGoc":"8"}]'::jsonb),
  ('VBH-HTL-02', 'Khi không có cạnh huyền, dùng $\tan$ hoặc $\cot$ để đi từ cạnh góc vuông này sang cạnh góc vuông kia.', 'Cạnh góc vuông $=$ cạnh góc vuông kia $\times \tan$ góc đối $= \times \cot$ góc kề.', '[{"de":"$AB = 3$, góc $B = 60^{\\circ}$, tìm $AC$.","giai":"Cách nghĩ sai: $AC = 3\\cdot \\tan 30^{\\circ} = \\sqrt{3}$. Cách đúng: $AC$ đối góc $B$ nên $AC = AB\\cdot \\tan 60^{\\circ} = 3\\sqrt{3}$."},{"de":"Bóng cột cờ $12$ m, nắng nghiêng $35^{\\circ}$, cột cao?","giai":"$h = 12\\cdot \\tan 35^{\\circ} \\approx 8{,}4$ m."}]'::jsonb, '[{"de":"$AB = 5$, góc $B = 45^{\\circ}$, $AC =$ ?","dapAn":"$5$","giaiThich":"$\\tan 45^{\\circ} = 1$.","dapAnGoc":"5"},{"de":"$AC = 9$, góc $C = 30^{\\circ}$, $AB =$ ?","dapAn":"$3\\sqrt{3}$","giaiThich":"$9\\cdot \\tan 30^{\\circ}$.","dapAnGoc":"3√3"}]'::jsonb),
  ('VBH-HTL-03', 'Bài đo đạc thực tế hay sai ở hai chỗ: chế độ máy tính và cách hiểu góc nâng, góc hạ.', 'Máy để chế độ độ $(D)$. Góc nâng, góc hạ đo giữa tia nhìn và phương nằm ngang. Vẽ hình, đánh dấu tam giác vuông, chọn tỉ số, làm tròn ở bước cuối.', '[{"de":"Từ nóc nhà cao $30$ m nhìn ô tô với góc hạ $25^{\\circ}$.","giai":"Cách nghĩ sai: khoảng cách $= 30\\cdot \\tan 25^{\\circ} \\approx 14$ m. Cách đúng: góc ở ô tô bằng $25^{\\circ}$ (so le trong), $\\tan 25^{\\circ} = \\dfrac{30}{d}$ nên $d = 30/\\tan 25^{\\circ} \\approx 64$ m."},{"de":"Tìm $\\alpha$ biết $\\sin \\alpha = 0{,}5$ bằng máy.","giai":"Chế độ $D$, bấm SHIFT $\\sin 0{,}5 = 30^{\\circ}$."}]'::jsonb, '[{"de":"$BC = 15$, góc $B = 40^{\\circ}$, $AC \\approx$ ?","dapAn":"$9{,}6$","giaiThich":"$15\\cdot \\sin 40^{\\circ}$.","dapAnGoc":"9,6"},{"de":"Máy hiện $0{,}52$ khi tìm góc có $\\sin = 0{,}5$ là do?","dapAn":"Chế độ radian","giaiThich":"Chuyển sang $D$.","dapAnGoc":"Chế độ radian"}]'::jsonb),
  ('VBH-HTL-04', 'Tam giác vuông đã có sẵn một góc $90^{\circ}$, nên hai góc còn lại chỉ "chia nhau" $90^{\circ}$.', 'Hai góc nhọn của tam giác vuông có tổng $90^{\circ}$. Giải tam giác vuông: tìm đủ $3$ cạnh và $2$ góc nhọn, cần biết ít nhất $2$ yếu tố trong đó có một cạnh.', '[{"de":"Góc $B = 35^{\\circ}$, tìm góc $C$.","giai":"Cách nghĩ sai: $180^{\\circ} - 35^{\\circ} = 145^{\\circ}$. Cách đúng: $90^{\\circ} - 35^{\\circ} = 55^{\\circ}$."},{"de":"$AB = AC = 5$, giải tam giác.","giai":"Vuông cân: góc $B =$ góc $C = 45^{\\circ}$, $BC = 5\\sqrt{2}$."}]'::jsonb, '[{"de":"Góc $C = 62^{\\circ}$, góc $B =$ ?","dapAn":"$28^{\\circ}$","giaiThich":"$90^{\\circ} - 62^{\\circ}$.","dapAnGoc":"28°"},{"de":"Biết hai góc nhọn có giải được tam giác vuông không?","dapAn":"Không","giaiThich":"Cần ít nhất một cạnh.","dapAnGoc":"Không"}]'::jsonb)
insert into mm_activities
  (activity_id, ten, error_codes, nhom, hinh_thuc, muc_nhan_thuc, phut_min, phut_max, mo_ta, hoc_lieu, trang_thai, nguon)
values
  ('HD-CBH-01', 'Hai căn hay một căn?', array['E-CBH-01', 'E-CBH-02']::text[], array['loi']::text[], 'nhom-dong-chat', 1, 7, 10, 'Nhóm nhận 12 thẻ (16; 0,25; −9; 0; √49; "căn bậc hai của 49"…). Xếp vào ba cột: có hai căn bậc hai – có một – không có; với mỗi thẻ ghi rõ √a và −√a. Nhóm tự phát biểu sự khác nhau giữa "căn bậc hai" và "căn bậc hai số học".', '12 thẻ số, bảng ba cột', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-CBH-02', 'Trị tuyệt đối dưới dấu căn', array['E-CBH-03', 'E-CBH-04']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 12, 'Nhóm thay lần lượt x = 5; 0; −5 vào √(x²) và vào x, ghi bảng so sánh, rồi phát biểu √(x²) = |x|. Sau đó tìm điều kiện xác định cho 4 căn thức (có căn ở mẫu) và kiểm tra bằng cách thay một giá trị biên.', 'Bảng thay số, 4 căn thức', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-KC-01', 'Căn của tổng có bằng tổng các căn?', array['E-KC-01', 'E-KC-02', 'E-BD-05']::text[], array['loi']::text[], 'ca-lop', 2, 6, 8, 'Cả lớp dùng máy tính cầm tay so sánh √(9 + 16) với √9 + √16, √(4 · 9) với √4 · √9, √2 + √3 với √5. Mỗi em giơ thẻ "bằng" hoặc "khác" trước khi bấm máy; giáo viên chốt quy tắc chỉ đúng với tích và thương.', 'Máy tính cầm tay, thẻ Bằng/Khác', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-KC-02', 'Khai căn thương từng bước', array['E-KC-03']::text[], array['loi']::text[], 'ca-nhan', 2, 5, 8, 'Học sinh làm 4 phép khai căn thương, bắt buộc viết bước trung gian √a / √b, rồi bạn cùng bàn kiểm tra bằng phép nhân ngược.', 'Phiếu 4 phép tính', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-BD-01', 'Ra – vào dấu căn', array['E-BD-01', 'E-BD-02']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 12, 'Mỗi nhóm nhận 8 thẻ cặp (√18 ↔ 3√2, −2√3 ↔ −√12, √(9x²y) ↔ …) có 3 thẻ ghép sai cài sẵn. Nhóm ghép, tìm thẻ sai và sửa, ghi rõ chỗ phải lấy |A| hoặc giữ dấu "−" ngoài căn.', '8 thẻ cặp biến đổi', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-BD-02', 'Bảng liên hợp', array['E-BD-03', 'E-BD-04']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 12, 'Nhóm điền bảng: mẫu → biểu thức liên hợp → tích của chúng (dạng a − b), cho 6 mẫu khác nhau; sau đó trục căn 3 biểu thức và đối chiếu với máy tính.', 'Phiếu bảng liên hợp, máy tính cầm tay', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-BD-03', 'Rút gọn tiếp sức', array['E-BD-05', 'E-BD-01', 'E-BD-03']::text[], array['loi']::text[], 'nhom-dong-chat', 3, 10, 15, 'Mỗi nhóm 4 em rút gọn một biểu thức theo kiểu tiếp sức: em 1 tìm điều kiện, em 2 đưa về căn đồng dạng hoặc trục căn, em 3 thu gọn, em 4 kiểm tra bằng thay số. Sai bước nào thì quay lại bước đó.', '3 biểu thức rút gọn, giấy A3', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-CBB-01', 'Căn bậc hai – căn bậc ba: giống và khác', array['E-CBB-01', 'E-CBB-02']::text[], array['loi']::text[], 'nhom-dong-chat', 1, 7, 10, 'Nhóm lập bảng so sánh căn bậc hai và căn bậc ba: số căn của số dương, của số âm, điều kiện xác định, √(A²) và ∛(A³). Kiểm tra bằng máy tính với các số −8, 8, −27, 0.', 'Phiếu bảng so sánh, máy tính cầm tay', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-C3-MR', 'Thiết kế hộp và sân chơi', array[]::text[], array['san-sang']::text[], 'nhom-dong-chat', 4, 12, 15, 'Nhóm đã làm chủ giải hai bài toán thực tế: tìm cạnh một sân hình vuông có diện tích cho trước (căn bậc hai) và cạnh một thùng hình lập phương có thể tích cho trước (căn bậc ba); làm tròn hợp lí và trình bày trên bảng phụ.', 'Hai bài toán thực tế, bảng phụ', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-PT2-01', 'Thẻ phương trình: đúng khuôn hay không?', array['E-PT2-01', 'E-PT2-03']::text[], array['loi']::text[], 'nhom-dong-chat', 1, 6, 8, 'Nhóm nhận 10 thẻ phương trình, xếp vào hai cột "bậc nhất hai ẩn" và "không phải", ghi a, b, c; với mỗi phương trình có a = 0 hoặc b = 0, vẽ nhanh đường thẳng nghiệm lên giấy kẻ ô.', '10 thẻ phương trình, giấy kẻ ô', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-HPT-01', 'Hai cửa kiểm tra', array['E-PT2-02', 'E-HPT-01']::text[], array['loi']::text[], 'ca-lop', 1, 5, 7, 'Giáo viên chiếu một hệ và 6 cặp số. Mỗi em giơ thẻ Đ/S cho từng phương trình rồi mới kết luận cặp số có là nghiệm của hệ không.', 'Thẻ Đ/S, slide 6 cặp số', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-HPT-02', 'Thế có ngoặc, cộng đủ hạng tử', array['E-HPT-02', 'E-HPT-03', 'E-HPT-04']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 10, 12, 'Mỗi nhóm có 4 lời giải mẫu có lỗi cài sẵn (quên ngoặc khi thế, nhân thiếu hạng tử, kết luận 0x = c sai). Nhóm khoanh lỗi, sửa và giải lại bằng cách còn lại để đối chiếu.', '4 lời giải có lỗi', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-BTH-01', 'Dịch đề sang hệ', array['E-BTH-01', 'E-BTH-02']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 10, 12, 'Nhóm nhận 3 đề bài, gạch chân từ khoá (tổng, hơn, gấp, chu vi, vượt mức), lập bảng "đại lượng – ẩn – điều kiện – phương trình" rồi trao đổi chéo để nhóm khác kiểm tra.', 'Phiếu bảng 4 cột, 3 đề bài', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-BTH-02', 'Sơ đồ chuyển động và bảng năng suất', array['E-BTH-03', 'E-BTH-04']::text[], array['loi']::text[], 'nhom-dong-chat', 3, 10, 15, 'Nhóm vẽ sơ đồ đoạn thẳng cho bài hai xe gặp nhau và bài ca nô xuôi – ngược dòng; lập bảng năng suất cho bài hai vòi nước. Từ sơ đồ, bảng lập hệ và giải.', 'Giấy A3, 3 đề bài', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-C1-MR', 'Bài toán thực tế của lớp', array[]::text[], array['san-sang']::text[], 'nhom-dong-chat', 4, 12, 15, 'Nhóm tự đặt một bài toán giải bằng hệ phương trình từ số liệu thật của lớp (giá đồ dùng, quãng đường đến trường), giải và đổi đề cho nhóm khác giải.', 'Giấy A4', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-PTT-01', 'Tích bằng 0 hay bằng số khác?', array['E-PTT-01', 'E-PTT-02']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 10, 'Nhóm nhận 6 phương trình (3 có vế phải bằng 0, 3 có vế phải khác 0) cùng lời giải của "bạn Nam" có lỗi chia cho x hoặc tách khi vế phải khác 0. Nhóm khoanh lỗi, giải lại và thử nghiệm bằng cách thay số.', '6 phương trình, lời giải có lỗi', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-PTM-01', 'Bốn bước có soát vé', array['E-PTM-01', 'E-PTM-02', 'E-PTM-03']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 10, 12, 'Mỗi nhóm giải 3 phương trình chứa ẩn ở mẫu trên phiếu có 4 ô bắt buộc: ĐKXĐ – khử mẫu – giải – đối chiếu. Có một phương trình vô nghiệm cài sẵn; nhóm nào kết luận đúng được điểm thưởng.', 'Phiếu 4 ô, 3 phương trình', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-BDT-01', 'Dấu nào cho lời nào?', array['E-BDT-01']::text[], array['loi']::text[], 'ca-lop', 1, 5, 7, 'Giáo viên đọc các câu đời sống (tốc độ tối đa, chiều cao tối thiểu, không quá 2 giờ…). Cả lớp giơ thẻ >, <, ≥, ≤ và giải thích một vài lựa chọn.', 'Bộ thẻ 4 dấu', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-BDT-02', 'Nhân số âm – lật chiều', array['E-BDT-02', 'E-BDT-03', 'E-BPT-02']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 10, 'Nhóm thử với cặp số cụ thể (2 < 5): cộng, trừ, nhân với 3, nhân với −3, chia −1 và ghi kết quả vào bảng, tự rút ra quy tắc đổi chiều; sau đó giải 4 bất phương trình có hệ số âm.', 'Bảng thử số, 4 bất phương trình', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-BPT-01', 'Trục số sống', array['E-BPT-01', 'E-BPT-03']::text[], array['loi']::text[], 'ca-lop', 1, 6, 8, 'Một dãy học sinh đứng thành trục số (−3 đến 5). Giáo viên đọc bất phương trình, các bạn là nghiệm bước lên; bạn ở điểm mút cầm thẻ ngoặc tròn hoặc vuông.', 'Thẻ số, thẻ ngoặc', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-C2-MR', 'Lập kế hoạch chi tiêu', array[]::text[], array['san-sang']::text[], 'nhom-dong-chat', 4, 12, 15, 'Nhóm có ngân sách cố định cho buổi ngoại khoá, lập bất phương trình cho số vé, số suất ăn tối đa, so sánh hai phương án thuê xe và trình bày lựa chọn.', 'Bảng giá giả định', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-TSLG-01', 'Tô màu đối – kề – huyền', array['E-TSLG-01', 'E-TSLG-02']::text[], array['loi']::text[], 'nhom-dong-chat', 1, 6, 8, 'Mỗi nhóm nhận 4 tam giác vuông đặt ở các tư thế khác nhau. Với góc được đánh dấu, tô đỏ cạnh đối, xanh cạnh kề, vàng cạnh huyền rồi viết 4 tỉ số. Đổi phiếu kiểm tra chéo.', 'Phiếu 4 tam giác, bút màu', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-TSLG-02', 'Dựng bảng góc đặc biệt', array['E-TSLG-03', 'E-TSLG-04']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 10, 'Nhóm cắt đôi một tam giác đều cạnh 2 và một hình vuông cạnh 1 bằng giấy, đo hoặc tính các cạnh để tự lập bảng sin, cos, tan của 30°, 45°, 60°; phát hiện quy luật sin α = cos(90° − α).', 'Giấy bìa, thước, kéo', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-HTL-01', 'Chọn đúng công cụ', array['E-HTL-01', 'E-HTL-02', 'E-HTL-04']::text[], array['loi']::text[], 'ca-lop', 2, 6, 8, 'Giáo viên chiếu 6 tam giác vuông với hai yếu tố đã biết và cạnh cần tìm. Học sinh giơ thẻ sin, cos, tan, cot (và nhân hay chia) trước khi tính; giáo viên hỏi lại vì sao.', 'Thẻ sin/cos/tan/cot, slide', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-HTL-02', 'Đo chiều cao cây trong sân trường', array['E-HTL-03']::text[], array['san-sang', 'loi']::text[], 'nhom-dong-chat', 3, 15, 20, 'Nhóm dùng giác kế tự chế (thước đo góc + dây dọi) đo góc nâng tới ngọn cây và khoảng cách đến gốc, tính chiều cao, so sánh kết quả giữa các nhóm và bàn về sai số.', 'Thước đo góc, dây dọi, thước dây', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-DTR-01', 'Trong – trên – ngoài', array['E-DTR-01', 'E-DTR-02']::text[], array['loi']::text[], 'ca-lop', 1, 5, 7, 'Giáo viên vẽ đường tròn bằng dây thừng trên sân hoặc bảng lớn. Học sinh nhận thẻ khoảng cách, đứng vào đúng vùng trong – trên – ngoài; sau đó gấp giấy hình tròn để đếm trục đối xứng.', 'Dây thừng, thẻ số, giấy tròn', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-CD-01', 'Nửa dây – bán kính – khoảng cách', array['E-CD-01']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 10, 'Nhóm vẽ đường tròn bằng compa, kẻ 3 dây, đo khoảng cách từ tâm và nửa dây rồi kiểm nghiệm OH² + AH² = R²; giải 3 bài tính dây.', 'Compa, thước, phiếu', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-CD-02', 'Đồng hồ cung tròn', array['E-CD-02', 'E-CD-03']::text[], array['loi']::text[], 'nhom-dong-chat', 1, 6, 8, 'Dùng mặt đồng hồ, nhóm xác định số đo cung nhỏ, cung lớn giữa hai kim ở 6 thời điểm; cộng các cung liên tiếp để kiểm tra tổng 360°.', 'Mô hình đồng hồ', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-QH-01', 'Ba công thức – ba tấm bìa', array['E-QH-01', 'E-QH-02', 'E-QH-03']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 10, 12, 'Nhóm cắt từ bìa một cung (sợi dây), một hình quạt và một vành khuyên; đo rồi so với kết quả tính theo l = πRn/180, S = πR²n/360, S = π(R² − r²). Ghi lại sai số.', 'Bìa, compa, kéo, dây', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-TT-01', 'Thước thẳng chạm đường tròn', array['E-TT-01', 'E-TT-02', 'E-TT-03']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 12, 'Nhóm đặt thước ở các khoảng cách khác nhau so với tâm, ghi d và số điểm chung; dựng tiếp tuyến bằng ê ke tại một điểm; kẻ hai tiếp tuyến từ một điểm ngoài, đo MA, MB và các góc để rút ra tính chất.', 'Compa, thước, ê ke, thước đo góc', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-HDT-01', 'Hai vòng tròn trượt', array['E-HDT-01', 'E-HDT-02']::text[], array['loi']::text[], 'ca-lop', 2, 6, 8, 'Dùng hai vòng bìa bán kính 5 cm và 3 cm, giáo viên trượt dần tâm này về phía tâm kia trên máy chiếu vật thể; học sinh ghi d và vị trí tương ứng để lập bảng so sánh với R + r, R − r.', 'Hai vòng bìa, máy chiếu vật thể', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-C5-MR', 'Thiết kế logo từ đường tròn', array[]::text[], array['san-sang']::text[], 'nhom-dong-chat', 4, 12, 15, 'Nhóm thiết kế một logo chỉ dùng đường tròn và tiếp tuyến (có ít nhất một cặp tiếp xúc ngoài, một tiếp tuyến chung), tính độ dài các cung và diện tích phần tô màu.', 'Giấy A4, compa', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-HSB-01', 'Bảng giá trị và parabol', array['E-HSB-01', 'E-HSB-02']::text[], array['loi']::text[], 'nhom-dong-chat', 1, 8, 10, 'Nhóm lập bảng giá trị y = 2x² và y = −x² với x từ −3 đến 3 (bắt buộc ghi bước bình phương), chấm điểm lên giấy kẻ ô và nối thành parabol; nhận xét trục đối xứng, hướng bề lõm.', 'Giấy kẻ ô, phiếu bảng giá trị', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-PTB-01', 'Xếp hàng rồi mới tính Δ', array['E-PTB-01', 'E-PTB-03']::text[], array['loi']::text[], 'ca-lop', 2, 6, 8, 'Giáo viên chiếu 6 phương trình viết lộn xộn. Học sinh viết lại dạng chuẩn, ghi a, b, c (hoặc b′) lên bảng con và tính Δ; giáo viên dừng ở các phương trình có b âm.', 'Bảng con, slide 6 phương trình', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-PTB-02', 'Ba ngã rẽ của Δ', array['E-PTB-02', 'E-PTB-04']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 10, 12, 'Mỗi nhóm nhận 8 thẻ phương trình (có khuyết b, khuyết c, Δ âm, Δ = 0), phân loại theo số nghiệm rồi giải; kiểm tra lại một nghiệm bằng cách thay vào phương trình.', '8 thẻ phương trình', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-VI-01', 'Đoán nghiệm nhanh', array['E-VI-01', 'E-VI-03', 'E-VI-04']::text[], array['loi']::text[], 'ca-lop', 2, 6, 8, 'Thi nhẩm nghiệm theo đội: giáo viên chiếu phương trình, đội nêu tổng – tích hoặc dấu hiệu a + b + c = 0, a − b + c = 0 rồi đọc nghiệm; đội khác kiểm tra bằng Viète.', 'Slide, bảng điểm', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-VI-02', 'Biểu thức đối xứng qua S và P', array['E-VI-02']::text[], array['loi']::text[], 'nhom-dong-chat', 3, 8, 10, 'Nhóm biến đổi 4 biểu thức đối xứng (x1² + x2², 1/x1 + 1/x2, x1/x2 + x2/x1, (x1 − x2)²) về S, P; áp dụng cho một phương trình có Δ > 0 và một phương trình vô nghiệm để thấy vì sao phải xét Δ.', 'Phiếu 4 biểu thức', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-LPT-01', 'Bảng ba dòng cho bài toán thực tế', array['E-LPT-01', 'E-LPT-02']::text[], array['loi']::text[], 'nhom-dong-chat', 3, 10, 15, 'Nhóm lập bảng "dự định – thực tế – quan hệ" cho bài toán xe đi sớm và đội may xong sớm, lập phương trình, giải và loại nghiệm; trình bày lí do loại nghiệm.', 'Giấy A3, 2 đề bài', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-C6-MR', 'Cổng parabol của trường', array[]::text[], array['san-sang']::text[], 'nhom-dong-chat', 4, 12, 15, 'Nhóm đo (hoặc dùng số liệu giả định) chiều rộng chân và chiều cao một cổng dạng parabol, tìm hệ số a của y = ax², kiểm tra một điểm trên cổng và đề xuất chiều cao xe tối đa đi qua.', 'Thước dây, giấy kẻ ô', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-TS-01', 'Kiểm đếm số liệu của lớp', array['E-TS-01', 'E-TS-02']::text[], array['loi']::text[], 'ca-lop', 1, 8, 10, 'Cả lớp ghi cỡ giày (hoặc số anh chị em) lên giấy ghi chú, dán lên bảng theo cột giá trị để thành biểu đồ cột sống; học sinh lập bảng tần số và kiểm tra tổng tần số bằng sĩ số.', 'Giấy ghi chú, bảng', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-TSTD-01', 'Từ số bạn sang phần trăm, sang độ', array['E-TSTD-01', 'E-TSTD-02']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 10, 12, 'Nhóm chuyển bảng tần số của lớp sang tần số tương đối, tính góc ở tâm rồi vẽ biểu đồ quạt bằng thước đo góc; kiểm tra tổng 100% và 360°.', 'Thước đo góc, compa, phiếu', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-GN-01', 'Cửa trái mở, cửa phải đóng', array['E-GN-01', 'E-GN-02']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 10, 'Nhóm nhận 30 thẻ chiều cao (có nhiều giá trị đúng bằng đầu mút), xếp vào các hộp nhóm [a; b), lập bảng tần số ghép nhóm và ước lượng chiều cao trung bình.', '30 thẻ số liệu, 5 hộp nhóm', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-GN-02', 'Biểu đồ liền cột', array['E-GN-03']::text[], array['loi']::text[], 'ca-nhan', 2, 6, 8, 'Học sinh vẽ biểu đồ cột và biểu đồ đoạn thẳng tần số tương đối ghép nhóm từ một bảng cho sẵn, rồi tìm 3 lỗi trong một biểu đồ vẽ sai (cột tách rời, điểm đặt ở đầu mút, tổng khác 100%).', 'Giấy kẻ ô, biểu đồ có lỗi', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-C7-MR', 'Khảo sát thời gian dùng điện thoại', array[]::text[], array['san-sang']::text[], 'nhom-dong-chat', 4, 15, 20, 'Nhóm khảo sát (ẩn danh) thời gian dùng điện thoại mỗi ngày của các bạn, ghép nhóm, vẽ biểu đồ tần số tương đối và đưa ra một lời khuyên dựa trên số liệu.', 'Phiếu khảo sát ẩn danh', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-XS-01', 'Sơ đồ cây và bảng 6 × 6', array['E-XS-01', 'E-XS-04']::text[], array['loi']::text[], 'nhom-dong-chat', 1, 8, 10, 'Nhóm vẽ sơ đồ cây cho phép tung đồng xu 2 lần, 3 lần và lập bảng 6 × 6 cho phép gieo hai xúc xắc; đếm số phần tử và so sánh với lời giải "6 + 6 = 12" để chỉ ra chỗ sai.', 'Phiếu sơ đồ cây, bảng 6 × 6', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-XS-02', 'Khoanh kết quả thuận lợi', array['E-XS-02', 'E-XS-03']::text[], array['loi']::text[], 'ca-nhan', 2, 6, 8, 'Trên bảng 6 × 6 đã có, học sinh khoanh các ô thuận lợi cho 4 biến cố (tổng bằng 7, hai mặt bằng nhau, tích chẵn, tổng lớn hơn 12) rồi tính xác suất; bạn cùng bàn kiểm tra.', 'Bảng 6 × 6', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-XS-03', 'Thực nghiệm gieo xúc xắc', array['E-XS-03']::text[], array['san-sang', 'loi']::text[], 'nhom-dong-chat', 3, 10, 12, 'Mỗi nhóm gieo hai xúc xắc 60 lần, ghi tần số tổng bằng 7, so tần số tương đối với xác suất lí thuyết 1/6; cả lớp gộp số liệu để thấy hai số tiến gần nhau.', 'Xúc xắc, phiếu ghi', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-C8-MR', 'Trò chơi có công bằng không?', array[]::text[], array['san-sang']::text[], 'nhom-dong-chat', 4, 12, 15, 'Nhóm phân tích một trò chơi (rút thẻ, gieo xúc xắc) do giáo viên đưa ra, tính xác suất thắng của mỗi người và đề xuất sửa luật để trò chơi công bằng.', 'Thẻ số, xúc xắc', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-GNT-01', 'Đo góc nội tiếp và góc ở tâm', array['E-GNT-01', 'E-GNT-02']::text[], array['loi']::text[], 'nhom-dong-chat', 1, 8, 10, 'Nhóm vẽ đường tròn, chọn một cung, vẽ góc ở tâm và ba góc nội tiếp cùng chắn cung đó, đo bằng thước đo góc để rút ra "bằng nửa" và "cùng chắn thì bằng nhau"; vẽ thêm góc chắn nửa đường tròn.', 'Compa, thước đo góc', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-NTT-01', 'Trung trực hay phân giác?', array['E-NTT-01', 'E-NTT-03']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 12, 'Mỗi nhóm có một tam giác bằng giấy: gấp các đường trung trực để tìm tâm ngoại tiếp và gấp các đường phân giác để tìm tâm nội tiếp, vẽ hai đường tròn và so sánh vị trí hai tâm.', 'Tam giác giấy, compa', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-NTT-02', 'Bán kính nhanh của tam giác đặc biệt', array['E-NTT-02']::text[], array['loi']::text[], 'ca-nhan', 2, 6, 8, 'Học sinh tính đường cao, R, r của tam giác đều cạnh 6 và R, r của tam giác vuông 6, 8, 10; so với đường tròn vẽ thật để kiểm tra.', 'Phiếu, compa', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-TGNT-01', 'Góc đối cộng 180°', array['E-TGNT-01', 'E-TGNT-02']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 10, 'Nhóm vẽ 3 tứ giác nội tiếp, đo bốn góc, cộng từng cặp góc đối; sau đó thử vẽ hình thoi, hình bình hành, hình chữ nhật nội tiếp và giải thích hình nào làm được.', 'Compa, thước đo góc', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-DGD-01', 'Xoay đa giác đều', array['E-DGD-01', 'E-DGD-02', 'E-PQ-01', 'E-PQ-02']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 10, 12, 'Nhóm cắt tam giác đều, hình vuông, lục giác đều bằng bìa, ghim tâm lên giấy và xoay; ghi các góc quay làm hình trùng lại chính nó và so với 360°/n; tính góc trong để phân biệt với góc quay.', 'Bìa, ghim, thước đo góc', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-C9-MR', 'Hoa văn từ đa giác đều', array[]::text[], array['san-sang']::text[], 'nhom-dong-chat', 4, 12, 15, 'Nhóm dựng một hoa văn lát nền từ lục giác đều và tam giác đều nội tiếp đường tròn, giải thích vì sao các viên ghép kín mặt phẳng dựa vào số đo góc.', 'Compa, giấy A4', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-TRU-01', 'Bóc vỏ lon nước', array['E-TRU-01', 'E-TRU-02']::text[], array['loi']::text[], 'nhom-dong-chat', 1, 8, 10, 'Nhóm cắt nhãn giấy quanh một lon hình trụ, trải phẳng thành hình chữ nhật, đo chiều dài và so với 2πr để tự rút ra Sxq = 2πrh; đo đường kính, tính bán kính và thể tích, so với dung tích ghi trên lon.', 'Lon nước, thước dây, kéo', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-NON-01', 'Chiều cao hay đường sinh?', array['E-NON-01', 'E-NON-02']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 10, 'Nhóm cuộn hình quạt giấy thành hình nón, đo chiều cao bằng que thẳng đứng và đo đường sinh dọc mặt nón, kiểm tra l² = h² + r²; đổ gạo từ hình nón sang hình trụ cùng đáy, cùng cao để thấy tỉ số 1/3.', 'Giấy bìa, gạo, cốc hình trụ', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-CAU-01', 'Quả cam và công thức hình cầu', array['E-CAU-01', 'E-CAU-02']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 10, 'Nhóm đo chu vi quả cam để tính bán kính, bóc vỏ trải vào 4 hình tròn lớn vẽ sẵn (bán kính bằng bán kính quả cam) để kiểm nghiệm S = 4πR²; tính thể tích quả cam.', 'Quả cam, thước dây, giấy vẽ 4 hình tròn', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-C10-MR', 'Thiết kế bồn chứa nước', array[]::text[], array['san-sang']::text[], 'nhom-dong-chat', 4, 12, 15, 'Nhóm thiết kế bồn chứa gồm hình trụ và hai nửa hình cầu có dung tích cho trước, tính kích thước và diện tích tôn cần dùng, so sánh hai phương án.', 'Phiếu đề bài', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng')
